examples:
// Basic usage with callback
<ImageUploader
  entityType="profile"
  onImagesUploaded={(urls) => console.log('Images uploaded:', urls)}
/>

// Single image upload with label
<ImageUploader
  entityType="avatar"
  maxImages={1}
  label="Profile Picture"
  description="Upload your profile picture"
  onImagesUploaded={(urls) => updateUserProfile({ avatarUrl: urls[0] })}
/>

// Multiple images for a gallery
<ImageUploader
  entityId={galleryId}
  entityType="gallery"
  maxImages={10}
  initialImages={existingImages}
  onImagesUploaded={(urls) => saveGalleryImages(urls)}
/>

// With existing images (edit mode)
<ImageUploader
  entityId={journalId}
  entityType="journal"
  initialImages={['/path/to/existing-image.jpg']}
  onImagesUploaded={(urls) => updateJournalImages(urls)}
/>

// Preserve original format (no conversion)
<ImageUploader
  entityType="artwork"
  preserveFormat={true}
  onImagesUploaded={(urls) => handleArtworkUpload(urls)}
/>

// Hide preview (upload only)
<ImageUploader
  entityType="document"
  hidePreview={true}
  onImagesUploaded={(urls) => processImages(urls)}
/>
